        c.strokeStyle = '#3a3550'; c.lineWidth = 1; for (i = 0; i < 4; i++) for (j = 0; j < 4; j++) { c.beginPath(); c.arc(10 + i * 4, 10 + j * 4, 1.1, 0, 7); c.stroke(); }
