      H.strokeRR(x + 10, ry + (rh - 5) / 2 - 9, 18, 18, 5, on ? PINK : '#c9c4d6', 1.5);
      if (on) { c.save(); c.strokeStyle = '#fff'; c.lineWidth = 2.4; c.lineCap = 'round'; c.beginPath(); c.moveTo(x + 14, ry + (rh - 5) / 2); c.lineTo(x + 18, ry + (rh - 5) / 2 + 4); c.lineTo(x + 24, ry + (rh - 5) / 2 - 4); c.stroke(); c.restore(); }
      var gd = (QT.Data.homes.GUESTS || []).filter(function (q) { return q.kind === g.kind; })[0];
      H.fitTxt(g.name, x + 38, ry + (rh - 5) * 0.32, 12, w * 0.5, g.ok ? INK : SOFT, 900, 9);
      var why = g.ok ? (gd ? L.nm(gd, 'note') : '') : (g.kind === 'vc' || g.kind === 'ovsInv' ? t('homesheet_full') : t('homesheet_done'));
      H.fitTxt(why, x + 38, ry + (rh - 5) * 0.72, 10, w - 50, g.ok ? '#2a8a5a' : SOFT, 700, 8);
